# Generated by trgen <version>
$generatedDir = Split-Path -Parent $MyInvocation.MyCommand.Path
$sourceRoot = '<source_root_unix>'
$java = if ($env:JAVA) { $env:JAVA } else { 'java' }
if (-not (Get-Command $java -ErrorAction SilentlyContinue)) {
    Write-Error "Java executable not found: $java"
    exit 1
}
Push-Location -LiteralPath $sourceRoot
try {
    $relativeFiles = @(& dotnet trash glob <source_glob_args_unix>)
    if ($LASTEXITCODE -ne 0) { throw 'Could not expand example-file globs.' }
} finally {
    Pop-Location
}

$files = [System.Collections.Generic.List[string]]::new()
foreach ($relative in $relativeFiles) {
    if (-not $relative -or $relative -match '\.(errors|tree|trq)$') { continue }
    $file = if ([IO.Path]::IsPathRooted($relative)) { $relative } else { Join-Path $sourceRoot $relative }
    if (Test-Path -LiteralPath $file -PathType Leaf) { $files.Add($file) }
}
if ($files.Count -eq 0) {
    Write-Host 'No test cases provided.'
    exit 0
}

$resultFile = [IO.Path]::GetTempFileName()
$failed = $false
Push-Location -LiteralPath $generatedDir
try {
    foreach ($file in $files) {
        & $java -cp classes Test -tree --no-output $file *> $resultFile
        $status = $LASTEXITCODE
        $expectedErrors = "$file.errors"
        $expectFailure = (Test-Path -LiteralPath $expectedErrors -PathType Leaf) -and
            ((Get-Item -LiteralPath $expectedErrors).Length -gt 0)
        if ($status -eq 0) {
            if ($expectFailure) {
                Write-Host "Expected a parse error: $file"
                $failed = $true
            } elseif (Test-Path -LiteralPath "$file.tree" -PathType Leaf) {
                $actual = ([IO.File]::ReadAllText($resultFile) -replace "`r`n", "`n").TrimEnd([char[]]@("`r", "`n"))
                $expected = ([IO.File]::ReadAllText("$file.tree") -replace "`r`n", "`n").TrimEnd([char[]]@("`r", "`n"))
                if ($actual -cne $expected) {
                    Write-Host "Tree differs: $file"
                    $failed = $true
                }
            }
        } elseif (-not $expectFailure) {
            Write-Host "Unexpected parse failure: $file"
            Get-Content -LiteralPath $resultFile | Write-Host
            $failed = $true
        }
    }
} finally {
    Pop-Location
    Remove-Item -LiteralPath $resultFile -ErrorAction SilentlyContinue
}
if ($failed) {
    Write-Host 'Test failed.'
    exit 1
}
Write-Host 'Test succeeded.'
